1: import { beforeAll, describe, expect, it } from "vitest";
2: import { renderToStaticMarkup } from "react-dom/server";
3: import StreamingMarkdownContent from "./StreamingMarkdownContent";
4: import { highlighterPromise } from "@/lib/highlighter";
5: 
6: beforeAll(async () => {
7:   await highlighterPromise;
8: });
9: 
10: function render(content: string, pageStack?: string[]) {
11:   return renderToStaticMarkup(
12:     <StreamingMarkdownContent
13:       content={content}
14:       browserToolResult={pageStack ? { page_stack: pageStack } : undefined}
15:     />,
16:   );
17: }
18: 
19: describe("StreamingMarkdownContent with real Streamdown and Shiki", () => {
20:   it("renders distinct upstream Markdown rather than fixed or empty output", () => {
21:     const first = render("Alpha **important**.");
22:     const second = render("Bravo *different*.");
23:     expect(first).toContain("Alpha");
24:     expect(first).toMatch(
25:       /<span\b[^>]*data-streamdown="strong"[^>]*>important<\/span>/,
26:     );
27:     expect(first).not.toContain("Bravo");
28:     expect(second).toContain("Bravo");
29:     expect(second).toMatch(/<em\b[^>]*>different<\/em>/);
30:     expect(second).not.toContain("Alpha");
31:   });
32: 
33:   it("renders the input code through the loaded syntax highlighter", () => {
34:     const first = render("```javascript\nconst answer = 42;\n```");
35:     const second = render("```javascript\nreturn false;\n```");
36:     expect(first).toContain("answer");
37:     expect(first).toContain("42");
38:     expect(first).toContain("color:");
39:     expect(first).not.toContain("false");
40:     expect(second).toContain("return");
41:     expect(second).toContain("false");
42:     expect(second).not.toContain("answer");
43:   });
44: 
45:   it("uses the citation cursor to select the correct upstream page", () => {
46:     const html = render("Evidence 【1†L2-L4】.", [
47:       "https://first.example/wrong-page",
48:       "https://second.example/right-page",
49:     ]);
50:     expect(html).toContain('href="https://second.example/right-page"');
51:     expect(html).not.toContain('href="https://first.example/wrong-page"');
52:     expect(html).toContain("[1]");
53:   });
54: 
55:   it("does not invent a link for a missing citation page", () => {
56:     const html = render("Evidence 【9†source】.");
57:     expect(html).toContain("[9]");
58:     expect(html).not.toContain("href=");
59:   });
60: 
61:   it("does not turn model-provided images or raw HTML into embedded resources", () => {
62:     const html = render(
63:       '![diagram](https://image.example/tracker)\n\n<iframe src="https://frame.example/embed"></iframe>',
64:     );
65:     expect(html).not.toContain("<img");
66:     expect(html).not.toContain("<iframe");
67:     expect(html).not.toContain('src="https://image.example');
68:     expect(html).not.toContain('src="https://frame.example');
69:     expect(html).toContain("diagram");
70:   });
